95	        .build_initial_context_with_world_state(step_context, world_state)
96	        .await;
97	    let (prefix, context) = split_prefix_updates(updates);
98	    let context = merge_world_state_updates(context);
99	    (
100	        assemble_compaction_history(compacted_history, prefix, context),
101	        snapshot,
102	    )
