181	async fn run_compact_task_inner(
182	    sess: Arc<Session>,
183	    turn_context: Arc<TurnContext>,
184	    replacement_step_context: Arc<StepContext>,
185	    input: Vec<UserInput>,
186	    world_state: Arc<WorldState>,
187	    compaction_metadata: CompactionTurnMetadata,
188	) -> CodexResult<()> {
189	    let trigger = compaction_metadata.trigger();
190	    let reason = compaction_metadata.reason();
191	    let phase = compaction_metadata.phase();
192	    let attempt = CompactionAnalyticsAttempt::begin(
193	        sess.as_ref(),
194	        turn_context.as_ref(),
195	        trigger,
196	        reason,
197	        CompactionImplementation::Responses,
198	        phase,
199	    )
200	    .await;
201	    let pre_compact_outcome = run_pre_compact_hooks(&sess, &turn_context, trigger).await;
202	    match pre_compact_outcome {
203	        PreCompactHookOutcome::Continue => {}
204	        PreCompactHookOutcome::Stopped => {
205	            let error = CodexErr::TurnAborted;
206	            attempt
207	                .track(
208	                    sess.as_ref(),
209	                    CompactionStatus::Interrupted,
210	                    Some(&error),
211	                    CompactionAnalyticsDetails::default(),
212	                )
213	                .await;
214	            return Err(error);
215	        }
216	    }
217	    let result = run_compact_task_inner_impl(
218	        Arc::clone(&sess),
219	        Arc::clone(&turn_context),
220	        replacement_step_context,
221	        input,
222	        world_state,
223	        compaction_metadata,
224	    )
225	    .await;
226	    let status = compaction_status_from_result(&result);
227	    let codex_error = result.as_ref().err();
228	    if result.is_ok() {
229	        let post_compact_outcome = run_post_compact_hooks(&sess, &turn_context, trigger).await;
230	        if let PostCompactHookOutcome::Stopped = post_compact_outcome {
231	            attempt
232	                .track(
233	                    sess.as_ref(),
234	                    status,
235	                    codex_error,
236	                    CompactionAnalyticsDetails::default(),
237	                )
238	                .await;
239	            return Err(CodexErr::TurnAborted);
240	        }
241	    }
242	    attempt
243	        .track(
244	            sess.as_ref(),
245	            status,
246	            codex_error,
247	            CompactionAnalyticsDetails::default(),
248	        )
249	        .await;
250	    if let Err(err) = &result
251	        && !matches!(phase, CompactionPhase::PostTurn)
252	        && !matches!(
253	            err.details(),
254	            CodexErrorDetails::Interrupted | CodexErrorDetails::TurnAborted
255	        )
256	    {
257	        sess.track_turn_codex_error(turn_context.as_ref(), err);
258	        // Pre-turn failures are reported after preserving the incoming prompt.
259	        if !matches!(phase, CompactionPhase::PreTurn) {
260	            let event = EventMsg::Error(err.to_error_event(/*message_prefix*/ None));
261	            sess.send_event(&turn_context, event).await;
262	        }
263	    }
264	    result.map(|_| ())
265	}
