267	async fn run_compact_task_inner_impl(
268	    sess: Arc<Session>,
269	    turn_context: Arc<TurnContext>,
270	    replacement_step_context: Arc<StepContext>,
271	    input: Vec<UserInput>,
272	    world_state: Arc<WorldState>,
273	    compaction_metadata: CompactionTurnMetadata,
274	) -> CodexResult<String> {
275	    let compaction_item = TurnItem::ContextCompaction(ContextCompactionItem::new());
276	    sess.emit_turn_item_started(&turn_context, &compaction_item)
277	        .await;
278	    let initial_input_for_turn: ResponseInputItem = ResponseInputItem::from(input);
279	
280	    let mut history = sess.clone_history().await;
281	    let input_goal_ids = UserGoalUpdate::message_ids(history.raw_items());
282	    history.record_items(
283	        &[initial_input_for_turn.into()],
284	        turn_context.model_info().truncation_policy.into(),
285	    );
286	    let mut fallback_instructions = sess.get_prompt_base_instructions().await;
287	    if let Some(text) = history
288	        .raw_items()
289	        .find_map(BaseInstructionsFragment::text_from_item)
290	    {
291	        fallback_instructions.text = text.to_owned();
292	    } else if history.has_tool_declarations() {
293	        // An incremental window has no recorded base item when its instructions are empty.
294	        fallback_instructions.text.clear();
295	    }
296	
297	    let max_retries = turn_context.provider.info().stream_max_retries();
298	    let mut retries = 0;
299	    // Reuse one client session so turn-scoped state (sticky routing and websocket incremental
300	    // request tracking) survives retries within this compact turn.
301	    let mut client_session = sess.services.model_client.new_session();
302	    let compaction_response = loop {
303	        // Clone is required because of the loop
304	        let mut turn_input = history
305	            .clone()
306	            .for_prompt(
307	                &turn_context.model_info().input_modalities,
308	                sess.services.image_store.as_ref(),
309	            )
310	            .await;
311	        sess.services
312	            .executed_tool_calls
313	            .attach_to_compaction_prompt(&mut turn_input);
314	        let turn_input_len = turn_input.len();
315	        let base_instructions = if turn_input
316	            .iter()
317	            .any(|item| BaseInstructionsFragment::text_from_item(item).is_some())
318	        {
319	            BaseInstructions {
320	                text: String::new(),
321	                provenance: None,
322	            }
323	        } else {
324	            fallback_instructions.clone()
325	        };
326	        let prompt = Prompt {
327	            input: turn_input,
328	            base_instructions,
329	            prompt_cache_ttl: turn_context.prompt_cache_ttl,
330	            cyber_access_program: turn_context.cyber_access_program,
331	            ..Default::default()
332	        };
333	        let responses_metadata = sess
334	            .compaction_responses_metadata(turn_context.as_ref(), compaction_metadata)
335	            .await;
336	        let attempt_result = drain_to_completed(
337	            &sess,
338	            turn_context.as_ref(),
339	            &mut client_session,
340	            &responses_metadata,
341	            &Arc::new(prompt),
342	            compaction_metadata.phase(),
343	        )
344	        .await;
345	
346	        match attempt_result {
347	            Ok(response) => {
348	                break response;
349	            }
350	            Err(e) if matches!(e.details(), CodexErrorDetails::ContextWindowExceeded) => {
351	                if turn_input_len > 1 {
352	                    // Trim from the beginning to preserve cache (prefix-based) and keep recent messages intact.
353	                    error!(
354	                        "Context window exceeded while compacting; removing oldest history item. Error: {e}"
355	                    );
356	                    history.remove_first_item();
357	                    retries = 0;
358	                    continue;
359	                }
360	                sess.set_total_tokens_full(turn_context.as_ref()).await;
361	                return Err(e);
362	            }
363	            Err(e) if retries < max_retries => {
364	                retries += 1;
365	                let Some(delay) = e.retry_delay(retries) else {
366	                    return Err(e);
367	                };
368	                let retry_after = e.retry_after();
369	                sess.notify_stream_error(
370	                    turn_context.as_ref(),
371	                    format!("Reconnecting... {retries}/{max_retries}"),
372	                    e,
373	                )
374	                .await;
375	                let retry_at = retry_after
376	                    .map(RetryAfter::deadline)
377	                    .unwrap_or_else(|| tokio::time::Instant::now() + delay);
378	                tokio::time::sleep_until(retry_at).await;
379	            }
380	            Err(e) => return Err(e),
381	        }
382	    };
383	
384	    let history_snapshot = sess.clone_history().await;
385	    let summary_suffix = if matches!(compaction_metadata.phase(), CompactionPhase::PostTurn) {
386	        get_last_assistant_message_from_turn(compaction_response.output.iter())
387	            .filter(|summary| !summary.trim().is_empty())
388	            .ok_or_else(|| {
389	                CodexErr::Stream(
390	                    "Post-turn compaction completed without an assistant summary".to_string(),
391	                )
392	            })?
393	    } else {
394	        get_last_assistant_message_from_turn(history_snapshot.raw_items()).unwrap_or_default()
395	    };
396	    let summary_text = format!("{SUMMARY_PREFIX}\n{summary_suffix}");
397	
398	    let mut new_history = build_compacted_history(&history_snapshot, &summary_text);
399	    if let Some(summary_item) = new_history.last_mut() {
400	        // This replacement history skips `record_conversation_items`; only the appended summary
401	        // belongs to this compaction turn.
402	        summary_item.set_turn_id_if_missing(&turn_context.sub_id);
403	    }
404	    // Use the final compactor input, so an overflow retry cannot restore discarded input.
405	    let pending_sequence =
406	        crate::compact_pending_input::pending_mail_sequence(history.annotated_items());
407	    if let Some(first) = pending_sequence {
408	        let summary = new_history
409	            .pop()
410	            .ok_or_else(|| CodexErr::Fatal("local compaction summary is missing".to_string()))?;
411	        // A client may also have explicitly retained this mail. Use the final
412	        // compactor input for pending mail so each delivery appears once.
413	        new_history.retain(|item| !is_retained_pending_mail(item, first));
414	        new_history.extend(
415	            history
416	                .annotated_items()
417	                .iter()
418	                .filter(|envelope| is_retained_pending_mail(envelope, first))
419	                .cloned(),
420	        );
421	        new_history.sort_by_key(|envelope| {
422	            envelope
423	                .metadata
424	                .as_ref()
425	                .and_then(|metadata| metadata.history_sequence)
426	        });
427	        new_history = crate::compact_remote_v2::truncate_retained_messages_for_remote_compaction(
428	            new_history,
429	            COMPACT_USER_MESSAGE_MAX_TOKENS,
430	            &history.file_audio_durations,
431	        );
432	        new_history =
433	            crate::compact_pending_input::insert_summary(new_history, summary, pending_sequence);
434	    }
435	    let rendered = world_state.render_full_with_host_roster().await;
436	    let (window_number, window_ids) = sess.advance_auto_compact_window().await;
437	    let (updates, world_state_baseline) = sess
438	        .assemble_initial_context(&replacement_step_context, rendered)
439	        .await;
440	    let (prefix, context) = split_prefix_updates(updates);
441	    let new_history =
442	        assemble_compaction_history(new_history, prefix, merge_world_state_updates(context));
443	    sess.replace_compacted_history(
444	        new_history,
445	        replacement_step_context.to_turn_context_item(),
446	        world_state_baseline,
447	        /*rejected_audio_file_ids*/ Default::default(),
448	        CompactedHistoryMetadata {
449	            input_goal_ids,
450	            message: summary_text,
451	            window_number,
452	            window_ids,
453	            compaction_response_id: Some(compaction_response.response_id),
454	            compaction_model_hash: turn_context.model_info().comp_hash.clone(),
455	            reviewer_compaction_hash: None,
456	        },
457	    )
458	    .await;
459	    sess.recompute_token_usage(&replacement_step_context.turn)
460	        .await;
461	
462	    sess.emit_turn_item_completed(&turn_context, compaction_item)
463	        .await;
464	    Ok(summary_suffix)
465	}
466	
