468	    thread_id: String,
469	    turn_id: String,
470	    trigger: CompactionTrigger,
471	    reason: CompactionReason,
472	    implementation: CompactionImplementation,
473	    phase: CompactionPhase,
474	    active_context_tokens_before: i64,
475	    started_at: u64,
476	    start_instant: Instant,
477	}
478	
479	#[derive(Clone, Copy, Default)]
480	pub(crate) struct CompactionAnalyticsDetails {
481	    pub(crate) active_context_tokens_before: Option<i64>,
482	    pub(crate) retained_image_count: Option<usize>,
483	    pub(crate) compaction_summary_tokens: Option<i64>,
484	    pub(crate) cached_input_tokens: Option<i64>,
485	    pub(crate) cache_write_input_tokens: Option<i64>,
486	}
487	
488	impl CompactionAnalyticsAttempt {
489	    pub(crate) async fn begin(
490	        sess: &Session,
491	        turn_context: &TurnContext,
492	        trigger: CompactionTrigger,
493	        reason: CompactionReason,
494	        implementation: CompactionImplementation,
495	        phase: CompactionPhase,
496	    ) -> Self {
497	        let active_context_tokens_before = sess.get_total_token_usage().await;
498	        Self {
499	            thread_id: sess.thread_id.to_string(),
500	            turn_id: turn_context.sub_id.clone(),
501	            trigger,
502	            reason,
503	            implementation,
504	            phase,
505	            active_context_tokens_before,
506	            started_at: now_unix_seconds(),
507	            start_instant: Instant::now(),
508	        }
509	    }

