fn deserialize_mcp_attribution_checkpoint<'de, D>(
    deserializer: D,
) -> Result<Option<McpAttribution>, D::Error>
where
    D: Deserializer<'de>,
{
    let value = serde_json::Value::deserialize(deserializer)?;
    Ok(Some(serde_json::from_value(value).unwrap_or_else(|_| {
        McpAttribution {
            status: McpAttributionStatus::AttributionError,
            error_reason: None,
            sources: Vec::new(),
        }
    })))
}

impl CodexHarnessMetadata {
    /// Shortened messages no longer prove complete instruction or review delivery.
    pub fn mark_retained_sources_incomplete(&mut self) {
        self.guardian_review_ids.clear();
        self.guardian_source_order_guidance = false;
        self.guardian_retained_omissions = None;
        if let Some(source) = &mut self.retained_source {
            source.complete = false;
        }
        for source in &mut self.guardian_sources {
            source.complete = false;
        }
    }
}

impl ResponseItemEnvelope {
    /// Whether the client requested that this item survive context-window changes and forks.
    pub fn is_always_retained(&self) -> bool {
        self.metadata
            .as_ref()
            .is_some_and(|metadata| metadata.retain_across_windows == Some(true))
    }

    /// Wraps a raw Responses API item for persisted history.
    pub fn new(item: ResponseItem) -> Self {
        Self {
            item,
            metadata: None,
        }
    }

    /// Unwraps the raw Responses API item.
    pub fn into_item(self) -> ResponseItem {
        self.item
    }
}

impl From<ResponseItem> for ResponseItemEnvelope {
    fn from(item: ResponseItem) -> Self {
        Self::new(item)
    }
}

impl From<InjectedResponseItem> for ResponseItemEnvelope {
    fn from(injected: InjectedResponseItem) -> Self {
        let mut envelope = Self::new(injected.item);
        if injected.retention != ItemRetention::Unspecified {
            envelope
                .metadata
                .get_or_insert_default()
                .retain_across_windows = Some(injected.retention == ItemRetention::Always);
        }
        envelope
    }
use std::sync::Arc;

use crate::context::world_state::WorldState;
use crate::hook_runtime::PostCompactHookOutcome;
use crate::hook_runtime::PreCompactHookOutcome;
use crate::hook_runtime::run_post_compact_hooks;
use crate::hook_runtime::run_pre_compact_hooks;
use crate::session::session::Session;
use crate::session::step_context::StepContext;
use codex_analytics::CompactionTrigger;
use codex_protocol::error::CodexErr;
use codex_protocol::error::Result as CodexResult;
use codex_protocol::items::ContextCompactionItem;
use codex_protocol::items::TurnItem;

/// Runs token-budget manual compaction as a normal compaction lifecycle.
///
/// Token-budget compaction skips model/server summarization and installs a fresh context window
/// instead. It is still modeled as compaction so compact hooks and `ContextCompaction` turn items
/// observe the same lifecycle as local or remote compaction.
pub(crate) async fn run_manual_compact_task(
    sess: Arc<Session>,
    step_context: Arc<StepContext>,
    world_state: Arc<WorldState>,
) -> CodexResult<()> {
    run_compact_task_inner(&sess, &step_context, world_state, CompactionTrigger::Manual).await
}

/// Runs token-budget inline auto-compaction as a normal compaction lifecycle.
///
/// Token-budget compaction skips model/server summarization and installs a fresh context window
/// instead. It is still modeled as compaction so compact hooks and `ContextCompaction` turn items
/// observe the same lifecycle as local or remote compaction.
pub(crate) async fn run_inline_auto_compact_task(
    sess: Arc<Session>,
    step_context: Arc<StepContext>,
    world_state: Arc<WorldState>,
) -> CodexResult<()> {
    run_compact_task_inner(&sess, &step_context, world_state, CompactionTrigger::Auto).await
}

async fn run_compact_task_inner(
    sess: &Arc<Session>,
    step_context: &Arc<StepContext>,
    world_state: Arc<WorldState>,
    trigger: CompactionTrigger,
) -> CodexResult<()> {
    let turn_context = &step_context.turn;
    let pre_compact_outcome = run_pre_compact_hooks(sess, turn_context, trigger).await;
    match pre_compact_outcome {
        PreCompactHookOutcome::Continue => {}
        PreCompactHookOutcome::Stopped => return Err(CodexErr::TurnAborted),
    }

    let compaction_item = TurnItem::ContextCompaction(ContextCompactionItem::new());
    sess.emit_turn_item_started(turn_context, &compaction_item)
        .await;
    sess.start_new_context_window(step_context, world_state)
        .await;
    sess.emit_turn_item_completed(turn_context, compaction_item)
        .await;

    let post_compact_outcome = run_post_compact_hooks(sess, turn_context, trigger).await;
    if let PostCompactHookOutcome::Stopped = post_compact_outcome {
        return Err(CodexErr::TurnAborted);
    }

    Ok(())
}
